package org.apache.lucene.queries.intervals;

import java.io.IOException;
import org.apache.lucene.search.DocIdSetIterator;

/**
 * A {@link DocIdSetIterator} which is a disjunction of the approximations of the provided
 * iterators.
 *
 * @lucene.internal
 */
class DisjunctionDISIApproximation extends DocIdSetIterator {

  final DisiPriorityQueue subIterators;
  final long cost;

  public DisjunctionDISIApproximation(DisiPriorityQueue subIterators) {
    this.subIterators = subIterators;
    long cost = 0;
    for (DisiWrapper w : subIterators) {
      cost += w.cost;
    }
    this.cost = cost;
  }

  @Override
  public long cost() {
    return cost;
  }

  @Override
  public int docID() {
    return subIterators.top().doc;
  }

  @Override
  public int nextDoc() throws IOException {
    DisiWrapper top = subIterators.top();
    final int doc = top.doc;
    do {
      top.doc = top.approximation.nextDoc();
      top = subIterators.updateTop();
    } while (top.doc == doc);

    return top.doc;
  }

  @Override
  public int advance(int target) throws IOException {
    DisiWrapper top = subIterators.top();
    do {
      top.doc = top.approximation.advance(target);
      top = subIterators.updateTop();
    } while (top.doc < target);

    return top.doc;
  }
}
abstract class ConjunctionIntervalIterator extends IntervalIterator {

  final DocIdSetIterator approximation;
  final List<IntervalIterator> subIterators;
  final float cost;

  ConjunctionIntervalIterator(List<IntervalIterator> subIterators) {
    this.approximation = ConjunctionUtils.intersectIterators(subIterators);
    this.subIterators = subIterators;
    float costsum = 0;
    for (IntervalIterator it : subIterators) {
      costsum += it.matchCost();
    }
    this.cost = costsum;
  }

  @Override
  public int docID() {
    return approximation.docID();
  }

  @Override
  public int nextDoc() throws IOException {
    int doc = approximation.nextDoc();
    if (doc != NO_MORE_DOCS) {
      reset();
    }
    return doc;
  }

  @Override
  public int advance(int target) throws IOException {
    int doc = approximation.advance(target);
    if (doc != NO_MORE_DOCS) {
      reset();
    }
    return doc;
  }

  protected abstract void reset() throws IOException;

  @Override
  public long cost() {
    return approximation.cost();
  }

  @Override
  public final float matchCost() {
    return cost;
  }
}

